"""Write the frozen, source-audited dev/test benchmark (labels are not sent to the agent)."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parents[1]/"data"/"advanced_questions.json"
SRC="UNDP Human Development Report 2023/24, English edition"
def q(id,split,cat,question,answer,evidence,answerable=True,notes=""):
    gold=[]
    for page,quote,kind in evidence:
        gold.append({"source":SRC,"page":page,"kind":kind,"evidence":quote,"visual_locator":f"Physical PDF page {page}; see indexed page crop if applicable"})
    return {"id":id,"split":split,"main_category":cat,"question":question,"answerable":answerable,
      "expected_answer":answer,"gold":gold,"review_note":notes}

items=[]
# DEV: 15 answerable (3 each of the five main categories) + 3 absent.
items += [
q("D-T01","dev","table","What rank and GNI per capita does Table 1 report for Switzerland? Include the GNI unit.","Rank 1; GNI per capita $69,433 in 2017 PPP dollars.",[(288,"1 Switzerland 0.967 84.3 16.6 13.9 69,433","table")]),
q("D-T02","dev","table","What HDI rank and value does Table 1 report for Norway?","Rank 2; HDI 0.966.",[(288,"2 Norway 0.966 83.4","table")]),
q("D-T03","dev","table","Table 3.1 gives what provision prognosis for a best-shot global public good?","It is likely to be provided if incentives are strong enough for the best shooter to contribute.",[(91,"Best-shot ... Likely to be provided if incentives are strong enough for the best shooter to contribute","table")]),
q("D-I01","dev","image_diagram","What does the central text in Figure 4.1 say the interaction is based on?","Public reasoning and procedures of social choice; the interaction is mutually dependent.",[(116,"Interactions are mutually dependent and based on public reasoning and procedures of social choice","diagram")]),
q("D-I02","dev","image_diagram","In Figure 2.4, what are the direct belief-related impacts listed after shocks?","Perceptions of threat and insecurity, and attitudes.",[(67,"Direct impact on beliefs (perceptions of threat, insecurity), attitudes","diagram")]),
q("D-I03","dev","image_diagram","Besides control over one's own life, what does the Figure S.7 infographic report about people's influence over government?","About 7 in 10 (68%) report little influence over what the government does.",[(23,"Voice in politics 7 in 10 or 68% report little influence over what the government does","infographic")]),
q("D-C01","dev","chart","In Figure 2.9, which HDI group has the highest median planetary-pressure index?","The very-high-HDI group.",[(71,"Figure 2.9 ... higher Human Development Index countries put higher pressures on the planet; central line is the median","chart")]),
q("D-C02","dev","chart","In Figure O.3, approximately what share of global GDP did the sum of exports and imports represent in 2022?","About 60%.",[(29,"Figure O.3 Sum of global exports and imports as a share of global GDP; 2022 is near 60%","chart")]),
q("D-C03","dev","chart","Looking at the right-hand panel of Figure 1.9 on physical PDF page 52, which named HDI group has its median below the zero line?","The very high HDI group.",[(52,"Very high HDI median is below zero on the projected additional extreme-temperature-days panel","chart")]),
q("D-M01","dev","multi_hop","Compare Tables 1 and 7 for Norway: what are its HDI and PHDI values, and what percentage reduction does Table 7 show?","HDI 0.966; PHDI 0.808; 16.4% lower than HDI.",[(288,"2 Norway 0.966","table"),(315,"2 Norway 0.966 0.808 16.4","table")]),
q("D-M02","dev","multi_hop","Use Table 3.1 and the discussion of best-shot goods on page 91: why can one country be enough to provide this type of good?","Because provision is determined by the contribution of the country contributing the most; one country may be sufficient to provide it fully.",[(91,"When the contribution of the country that contributes the most determines the level of provision ... Potentially only one country is enough","text"),(91,"Best-shot global public goods","table")]),
q("D-M03","dev","multi_hop","What is the report's two-part explanation for why the HDI recovery is incomplete, combining Figure S.1 and Figure S.2?","Global HDI remains below its pre-2019 trend, and recovery is unequal: many countries had not regained their 2019 HDI by 2023.",[(18,"A permanent shift in the Human Development Index trajectory","chart"),(18,"Recovery of Human Development Index ... Developed Countries are projected to have done so","chart")]),
q("D-X01","dev","text","How many people worldwide does the report say feel worried, stressed or sad?","Almost 3 billion people.",[(67,"Across the world almost 3 billion people report feeling worried, stressed or sad","text")]),
q("D-X02","dev","text","What within-country differences in Norway's fairness preferences does the report describe?","Egalitarian views are more common among 15-year-olds from low-socioeconomic-status households than high-status households; most grade 5 children are egalitarian, while the meritocratic share rises in higher grades and is largest in grade 13.",[(130,"In Norway the share of egalitarians is much higher among 15-year-olds from low socioeconomic households ... most grade 5 children are egalitarians ... meritocratic share increases in higher grades and is largest by grade 13","text")]),
q("D-X03","dev","text","For weakest-link public goods, what capacity-related recommendation does Table 3.1 give?","Capacity building is essential to enhance contributions of the least able and redistribute capacities among countries.",[(91,"Weakest link ... Capacity building is essential to enhance the contributions of those least able to contribute and to redistribute capacities among countries","table")]),
q("D-A01","dev","abstention","What was Vietnam's GDP growth rate in 2025 according to this report?","Abstain: the report does not provide a 2025 Vietnam GDP growth rate.",[],False,"Full report covers historical indicators through 2022/2023 projections; no 2025 Vietnam GDP growth figure."),
q("D-A02","dev","abstention","How many square kilometres of Amazon rainforest were deforested in calendar year 2024, according to the report?","Abstain: the report does not give that 2024 Amazon deforestation area.",[],False,"Search full extracted text for Amazon and 2024 deforestation area; no such figure."),
q("D-A03","dev","abstention","What was the voter turnout in Indonesia's 2024 presidential election according to this report?","Abstain: the report does not state that election turnout.",[],False,"The 2024 election result/turnout is not covered in the report."),
]
# TEST: exactly 24 answerable across required mutually-exclusive categories, plus 6 absent.
