q("T-X04","test","text","According to the Statistical Annex definition, what does PHDI adjust the HDI for?","Planetary pressures, including carbon dioxide emissions and material footprint.",[(315,"Planetary pressures-adjusted HDI (PHDI)","table"),(315,"Adjustment factor for planetary pressures Carbon dioxide emissions ... Material footprint","table")]),
q("T-A01","test","abstention","What was Vietnam's GDP growth rate in 2025 according to this report?","Abstain: the report provides no 2025 Vietnam GDP growth rate.",[],False,"No 2025 Vietnam growth figure in report; Vietnam string does not provide such figure."),
q("T-A02","test","abstention","How many square kilometres of Amazon rainforest were deforested in calendar year 2024, according to the report?","Abstain: this report does not state a 2024 Amazon deforestation area.",[],False,"Full-text scan found no 2024 Amazon deforestation area."),
q("T-A03","test","abstention","What was the voter turnout in Indonesia's 2024 presidential election according to this report?","Abstain: this election turnout is not reported.",[],False,"No evidence in source for this 2024 election turnout."),
